func (t *dropCollectionFunctionTask) PreExecute(ctx context.Context) error {
	coll, err := getCollectionInfo(...)
	if err != nil { return err }
	for _, f := range coll.schema.Functions {
		if f.Name == t.FunctionName { t.fSchema = f; break }
	}
	return nil
}
func (t *dropCollectionFunctionTask) Execute(ctx context.Context) error {
	if t.fSchema == nil { return nil }        // <-- 不存在的 function: 静默返回 nil = 幂等成功
	if t.fSchema.Type == schemapb.FunctionType_BM25 { return fmt.Errorf("currently does not support droping BM25 function") }
	...DropCollectionFunction...
}
-- not-found 无任何错误分支；集合不存在时才报错(getCollectionInfo)。大小写双拼写: Go json unmarshal 对无精确 tag 匹配的键做大小写不敏感回退，'functionName' 也能填充 FunctionName 字段。
